from typing import List

class Solution:
    def lengthOfLongestSubsequence(self, nums: List[int], target: int) -> int:
        dp = {0: 0}  # sum: max_length
        for num in nums:
            # Iterate through a copy of current keys to avoid modifying during iteration
            current_sums = list(dp.keys())
            for s in current_sums:
                new_sum = s + num
                if new_sum > target:
                    continue
                new_len = dp[s] + 1
                if new_sum not in dp or new_len > dp[new_sum]:
                    dp[new_sum] = new_len
        return dp.get(target, -1)

