class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        n = len(nums)
        min_diff = float('inf')

        for i in range(n):
            # Check elements to the left (j <= i - x)
            for j in range(i - x, -1, -1):
                min_diff = min(min_diff, abs(nums[i] - nums[j]))

            # Check elements to the right (j >= i + x)
            for j in range(i + x, n):
                min_diff = min(min_diff, abs(nums[i] - nums[j]))

        return min_diff
